{"code": "const zlib = await import("node:zlib");
const hasZstd = typeof (zlib as any).zstdDecompressSync === "function";
console.log("node zstd support:", hasZstd, "node", process.version);
const fs = await import("node:fs");
const path = await import("node:path");
const root = "C:\\Users\\Administrator\\.dsh\\sessions\\--D-lean--";
const dirs = fs.readdirSync(root);
let files: {p:string; size:number; mtime:number}[] = [];
for (const d of dirs) {
  const f = path.join(root, d, "session.v4.jsonl.zstd");
  if (fs.existsSync(f)) { const st = fs.statSync(f); files.push({p:f, size:st.size, mtime:st.mtimeMs}); }
}
files.sort((a,b)=>b.mtime-a.mtime);
console.log("total", files.length);
console.log("top 12 by mtime:");
for (const f of files.slice(0,12)) console.log(new Date(f.mtime).toISOString(), f.size, f.p.slice(root.length+1));
const today = files.filter(f => (Date.now()-f.mtime) < 6*3600*1000);
console.log("modified last 6h:", today.length, "bytes:", today.reduce((a,b)=>a+b.size,0));
", "description": "Check zstd support and recent session files"}

